-- tags: created by `forge generate scaffold` for MySQL/MariaDB.
-- Identifiers are UUIDv7 values generated by the application; the
-- database never generates them. `version` is the optimistic lock.

CREATE TABLE `tags` (
    `id` BINARY(16) NOT NULL PRIMARY KEY,
    `label` VARCHAR(255) NOT NULL,
    `active` BOOLEAN,
    `version` BIGINT NOT NULL DEFAULT 1,
    `created_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    `updated_at` DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    CONSTRAINT `tags_version_positive` CHECK (`version` >= 1)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4;
